#include <stdint.h>
#include <math.h>

float vectorized_s318(int iterations, int LEN_1D, float* a, int inc)
{
    float max, chksum = 0.0f;
    for (int nl = 0; nl < iterations; nl++) {
        int k = 0;
        int index = 0;
        max = fabsf(a[0]);
        k += inc;
        int i = 1;
        // Process elements in order to preserve exact comparison semantics
        for (; i < LEN_1D; i++) {
            float val = fabsf(a[k]);
            if (val > max) {
                index = i;
                max = val;
            }
            k += inc;
        }
        chksum = max + (float) index;
    }
    return chksum + 1.0f;
}

#include <math.h>
#include <string.h>

float s318_opt(int iterations, int LEN_1D, float* a, int inc)
{
    int k, index;
    float max, chksum;

    for (int nl = 0; nl < iterations/2; nl++) {
        // Phase 1: Extract absolute values into temporary array
        float* abs_vals = (float*)malloc(LEN_1D * sizeof(float));
        k = 0;
        abs_vals[0] = fabsf(a[0]);
        k += inc;
        for (int i = 1; i < LEN_1D; i++) {
            abs_vals[i] = fabsf(a[k]);
            k += inc;
        }

        // Phase 2: Vectorizable max-finding on independent array
        max = abs_vals[0];
        index = 0;
        for (int i = 1; i < LEN_1D; i++) {
            float val = abs_vals[i];
            int cond = val > max;
            max = cond * val + (!cond) * max;
            index = cond * i + (!cond) * index;
        }

        free(abs_vals);
        chksum = max + (float) index;
    }
    return max + index + 1;
}
